const raw = String($input.first().json.data ?? $input.first().json);
const items = [];
const re = /<item>[\s\S]*?<title>([^<]*)<\/title>[\s\S]*?<source[^>]*>([^<]*)<\/source>/g;
let m = null;
while ((m = re.exec(raw)) && items.length < 15) { items.push({ title: m[1].trim().slice(0, 150), source: m[2].trim().slice(0, 40) }); }
return [{ json: { mentions: items, total: items.length } }];

const raw = String(($input.first().json.choices && $input.first().json.choices[0] && $input.first().json.choices[0].message && $input.first().json.choices[0].message.content) || '');
const lines = [];
const used = {};
const rawLines = raw.split('\n');
const headRe = /^\s*(Item\s*\d+\s*:|\d+\s*[.)\-\u2013:]\s*|[-\u2022]\s*)/i;
for (let li = 0; li < rawLines.length && lines.length < 7; li++) {
  if (used[li] || !headRe.test(rawLines[li])) continue;
  let chunk = (rawLines[li] + ' ' + (rawLines[li + 1] || '') + ' ' + (rawLines[li + 2] || '')).replace(/[*_#\[\]()]/g, ' ').replace(/\s+/g, ' ').trim();
  chunk = chunk.replace(/^(Item\s*\d+\s*:|[-\u2022]\s*|\d+\s*[.)\-\u2013:]\s*)/i, '').trim().slice(0, 240);
  const isEcho = /(prohibited|no explanation|outside the list|input data|format:|\bnote\b|identify|key themes|analysis:)/i.test(chunk);
  if (isEcho) continue;
  if (chunk.length > 25 && !/:$/.test(chunk)) { if (lines.indexOf(chunk) < 0) { lines.push(chunk); used[li] = 1; used[li + 1] = 1; used[li + 2] = 1; } }
}
if (!lines.length) throw new Error('Watch parse found zero moves');
const digest = 'مرصد المنافسين الاسبوعي\n\n' + lines.map((l, i) => (i + 1) + '. ' + l).join('\n\n');
return [{ json: { digest: digest.slice(0, 3500) } }];
